// the envelope close-up looks at the top of the long cut face at x = ENV_X; a point on that edge, `dep` below the surface, `behind` the face
const ENV_X = 4.2, topAt = (x, dep, behind) => edgePt('z', x / (2 * H + Math.PI * (R - dep)), dep, behind);
// a membrane protein's turn: its file's z (out of the cell, as OPM lays them) along the outward normal n, spun at random round it
const zAx = V(0, 0, 1), qOut = (n, spin = rr(0, 6.283)) => new THREE.Quaternion().setFromUnitVectors(zAx, n).multiply(new THREE.Quaternion().setFromAxisAngle(zAx, spin));
