const RIBO = (g, part) => col(part === 2 ? (g ? '#e47aae' : '#f5b0d0') : (g ? '#8e6cd0' : '#b896e6'));
const RNAP_C = ['#6fd6c0', '#5aa6ff', '#7f8cff', '#ffd24f', '#ff8a5c'], RNAP = g => col(RNAP_C[g]);
