  cell.add(shade(new THREE.Mesh(rodGeo(R), omMat), false, false));
  cell.add(new THREE.Mesh(rodGeo(R - OM, 40, 120), reg('om', phys({ color: '#3d6b5e', roughness: .75, side: THREE.BackSide }))));
  cell.add(new THREE.Mesh(rodGeo(R - (PG0 + PG1) / 2, 48, 160), reg('pg', phys({ color: '#f0d26e', emissive: '#6b4f0e', emissiveIntensity: .25, roughness: .5, alphaMap: pgTex(), alphaTest: .5, side: THREE.DoubleSide }))));
  // inner membrane: opaque, so the inside shows only through the cut
