  const duplex = (pts, a, b) => { const ax = curve(pts, BP); BACKBONE[0] = a; BACKBONE[1] = b; emitDNA(DNA, ax); BACKBONE[0] = PAR[0]; BACKBONE[1] = PAR[1]; mark(ax); return ax; };
  const single = (pts, bb) => { const ax = Array.isArray(pts[0]) ? curve(pts, NT) : resample(pts, NT); ssAlong(DNA, ax, bb); mark(ax); return ax; };
  const put = (key, at, q, colour) => { placeMol(S, key, at, q, colour, true); gMol(key, at, q); return at; };
  const along = (d, spin = rr(0, 6.283)) => new THREE.Quaternion().setFromUnitVectors(zAx, d.clone().normalize()).multiply(new THREE.Quaternion().setFromAxisAngle(zAx, spin));
