// free look: W and S move along the view, A and D sideways; the camera and the point it turns around move together,
// so dragging still turns the view as before. Steps scale with the zoom, so moving feels the same close up and far away
const held = new Set();
addEventListener('keydown', e => { const k = e.key.toLowerCase(); if (k.length === 1 && 'wasd'.includes(k) && !e.target.closest?.('input, textarea') && !e.metaKey && !e.ctrlKey) held.add(k); });
addEventListener('keyup', e => held.delete(e.key.toLowerCase()));
addEventListener('blur', () => held.clear());
const fwd = V(), side = V(), step = V();
// mouse look: a left-drag turns the camera where it stands (drag right to look right, down to look down) instead of swinging
// it around the cell; the point the camera looks at is moved in front of it, so scrolling and right-drag panning still work
controls.enableRotate = false;
let lookFrom = null;
const aim = new THREE.Spherical();
